import { atom, read, update } from 'claude-code'
import type { Register, RenderElement } from 'claude-code'
import type { AgentRun, CallRow, Pulse, Todo, ToolStat } from '../types'

// pulse: one band above the prompt with what this session is doing right
// now (which tools ran and failed, which subagents run, how far the todo
// list has come), and a pane with the detail. Nothing leaves the machine.

const EMPTY: Pulse = { tools: [], lastTool: null, agents: [], todos: [], turnStartedAt: null, recent: [], turns: 0 }

const pulse = atom({ plugin: 'pulse', key: 'pulse' } as const, EMPTY)
const collapsed = atom({ plugin: 'pulse', key: 'collapsed' } as const, true)
const hidden = atom({ plugin: 'pulse', key: 'hidden' } as const, false)

const MAX_AGENTS_SHOWN = 4
const MAX_TOOLS_SHOWN = 6
const MAX_RECENT = 40
const RECENT_SHOWN = 12
const DONE_AGENT_TTL_MS = 60_000
const PANE = 'pulse'

type Host = Parameters<typeof update>[0]

// State written by an older pulse lacks the newer fields; fill them in.
const norm = (p: Partial<Pulse> | undefined): Pulse => ({
  ...EMPTY,
  ...(p ?? {}),
  tools: (p?.tools ?? []).map(t => ({ ...t, ms: t.ms ?? 0, lastAt: t.lastAt ?? null })),
  recent: p?.recent ?? [],
  turns: p?.turns ?? 0,
})
const readPulse = async ($: Host) => norm(await read($, pulse))
const edit = ($: Host, f: (p: Pulse) => Pulse) => update($, pulse, p => f(norm(p)))

// The band is one site: whichever plugin sits on top answers for it. pulse draws
// its own row and keeps whatever another plugin beneath it drew, stacked above it.
const isBlank = (el: unknown): boolean => {
  if (!el || typeof el !== 'object') return true
  const t = (el as { type?: unknown }).type
  if (t === 'engine') return true
  const kids = (el as { children?: unknown }).children
  return t === 'Box' && (!Array.isArray(kids) || kids.length === 0)
}

const short = (name: string) => name.startsWith('mcp__') ? name.split('__').slice(1).join(':') : name

// What a call was about, in a few words: a file's last two segments, else
// the call's own description, command, pattern, query or address.
const detailOf = (input: Record<string, unknown>): string => {
  const s = (k: string) => typeof input[k] === 'string' && (input[k] as string).length > 0 ? input[k] as string : undefined
  const path = s('file_path') ?? s('notebook_path') ?? s('path')
  if (path) return path.split('/').filter(Boolean).slice(-2).join('/')
  const text = s('description') ?? s('command') ?? s('pattern') ?? s('query') ?? s('url') ?? s('skill') ?? s('prompt') ?? ''
  return text.replace(/\s+/g, ' ').trim().slice(0, 160)
}

const since = (from: number, now: number) => {
  const s = Math.max(0, Math.round((now - from) / 1000))
  if (s < 60) return `${s}s`
  const m = Math.floor(s / 60)
  return m < 60 ? `${m}m${String(s % 60).padStart(2, '0')}s` : `${Math.floor(m / 60)}h${String(m % 60).padStart(2, '0')}m`
}

const ms = (n: number) => n < 1000 ? `${Math.round(n)}ms` : n < 60_000 ? `${(n / 1000).toFixed(1)}s` : since(0, n)

const bar = (done: number, total: number, width: number) => {
  if (total === 0) return '─'.repeat(width)
  const filled = Math.round((done / total) * width)
  return '█'.repeat(filled) + '░'.repeat(width - filled)
}

const agentGlyph = (a: AgentRun) => a.endedAt === null ? '●' : a.isError ? '✗' : '✓'
const agentColor = (a: AgentRun) => a.endedAt === null ? 'warning' : a.isError ? 'error' : 'success'
// Running agents first, then the newest.
const byLive = (a: AgentRun, b: AgentRun) => (a.endedAt === null ? 0 : 1) - (b.endedAt === null ? 0 : 1) || b.startedAt - a.startedAt

export const register: Register = on => {
  on('session.start', ($, e, next) => {
    $.command.register({ name: 'pulse', description: 'Show or hide the pulse band; "/pulse details" opens the pulse pane' })
    return next(e)
  })

  on('command.run', { command: 'pulse' }, async ($, e) => {
    if (/^\s*(details|pane|open)\s*$/i.test(e.args)) {
      const opened = await $.ui.open({ id: PANE, title: 'Pulse' })
      return { text: opened.isPlaced ? 'pulse: details pane opened.' : `pulse: pane waits (${opened.reason}).` }
    }
    const isHidden = await update($, hidden, v => !v)
    return { text: isHidden ? 'pulse: band hidden. /pulse shows it again.' : 'pulse: band shown.' }
  }).catch(() => ({ text: 'pulse: could not toggle' }))

  on('prompt.submit', async ($, e, next) => {
    const now = await $.clock.now()
    await edit($, p => ({
      ...p,
      turnStartedAt: now,
      turns: p.turns + 1,
      tools: p.tools.map(t => ({ ...t, busy: 0 })),
      agents: p.agents.filter(a => a.endedAt === null || now - a.endedAt < DONE_AGENT_TTL_MS),
    }))
    return next(e)
  }).catch(($, e, next) => next(e))

  on('agent.spawn', async ($, e, next) => {
    const result = await next(e)
    if (result.deny !== undefined || !result.agentId) return result
    const now = await $.clock.now()
    const run: AgentRun = { id: result.agentId, type: e.subagentType, description: e.description, startedAt: now, endedAt: null, isError: false }
    await edit($, p => ({ ...p, agents: [...p.agents.filter(a => a.id !== run.id), run] }))
    return result
  }).catch(($, e, next) => next(e))

  on('tool.call', async ($, e, next) => {
    const name = short(e.tool)
    const isMain = e.agentId === undefined
    const startedAt = await $.clock.now()
    const id = e.tool_use_id ?? `${name}@${startedAt}`

    // The main loop's calls are the session's activity; a subagent's are its own.
    if (isMain) {
      const row: CallRow = { id, tool: name, detail: detailOf(e as unknown as Record<string, unknown>), startedAt, endedAt: null, isError: false }
      await edit($, p => {
        const tools = p.tools.some(t => t.name === name)
          ? p.tools.map(t => t.name === name ? { ...t, calls: t.calls + 1, busy: t.busy + 1 } : t)
          : [...p.tools, { name, calls: 1, errors: 0, busy: 1, ms: 0, lastAt: null } satisfies ToolStat]
        return { ...p, tools, lastTool: name, recent: [...p.recent, row].slice(-MAX_RECENT) }
      })
    }

    if (e.tool === 'TodoWrite') {
      const todos: Todo[] = e.todos.map(t => ({ content: t.content, activeForm: t.activeForm, status: t.status }))
      await edit($, p => ({ ...p, todos }))
    }

    const result = await next(e)
    const isError = result.deny !== undefined || result.isError === true
    const endedAt = await $.clock.now()

    if (isMain) {
      await edit($, p => ({
        ...p,
        tools: p.tools.map(t => t.name === name
          ? { ...t, busy: Math.max(0, t.busy - 1), errors: t.errors + (isError ? 1 : 0), ms: t.ms + (endedAt - startedAt), lastAt: endedAt }
          : t),
        recent: p.recent.map(r => r.id === id ? { ...r, endedAt, isError } : r),
      }))
    }

    if (e.tool === 'Agent' && result.deny === undefined) {
      const live = await $.agent.list()
      const alive = new Set(live.map(a => a.id))
      await edit($, p => ({
        ...p,
        agents: p.agents.map(a => a.endedAt === null && !alive.has(a.id) ? { ...a, endedAt, isError } : a),
      }))
    }

    return result
  }).catch(($, e, next) => next(e))

  on('turn.complete', async ($, e, next) => {
    const now = await $.clock.now()
    const live = await $.agent.list()
    const alive = new Set(live.map(a => a.id))
    await edit($, p => ({
      ...p,
      turnStartedAt: null,
      tools: p.tools.map(t => ({ ...t, busy: 0 })),
      // A call still open when the turn ends was cut off.
      recent: p.recent.map(r => r.endedAt === null ? { ...r, endedAt: now } : r),
      agents: p.agents.map(a => a.endedAt === null && !alive.has(a.id) ? { ...a, endedAt: now } : a),
    }))
    return next(e)
  })

  // The band: one row, a glance at the session. Open, it adds the busiest tools
  // and this session's agents, each row named. Detail lives in the pane.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const p = await readPulse($)
    const isCollapsed = await read($, collapsed)
    const isHidden = await read($, hidden)
    const isEmpty = p.tools.length === 0 && p.agents.length === 0 && p.todos.length === 0
    if (e.props.hasSurvey || isHidden || isEmpty) return next(e)

    const { Box, Text, Button } = $.ui.resolve(e)
    const now = await $.clock.now()

    const running = p.agents.filter(a => a.endedAt === null)
    const done = p.todos.filter(t => t.status === 'completed').length
    const current = p.todos.find(t => t.status === 'in_progress')
    const calls = p.tools.reduce((n, t) => n + t.calls, 0)
    const errors = p.tools.reduce((n, t) => n + t.errors, 0)
    const busy = p.tools.filter(t => t.busy > 0)

    const tools = (
      <Box gap={1} flexShrink={1}>
        <Text color={busy.length > 0 ? 'claude' : 'subtle'}>{busy.length > 0 ? '◆' : '◇'}</Text>
        <Text bold tabular>{calls}</Text>
        <Text dimColor>{calls === 1 ? 'tool call' : 'tool calls'}</Text>
        {errors > 0 ? <Text color="error">{`· ${errors} failed`}</Text> : null}
        {busy.length > 0
          ? <Text color="claude" wrap="truncate-end">{`· running ${busy.map(t => t.name).join(', ')}`}</Text>
          : p.lastTool ? <Text dimColor wrap="truncate-end">{`· last ${p.lastTool}`}</Text> : null}
      </Box>
    )
    const agents = (
      <Box gap={1} flexShrink={1}>
        <Text color={running.length > 0 ? 'warning' : 'subtle'}>{running.length > 0 ? '●' : '○'}</Text>
        {running.length > 0 ? <Text bold tabular>{running.length}</Text> : null}
        <Text dimColor>{running.length === 0 ? 'No agents running' : running.length === 1 ? 'agent running' : 'agents running'}</Text>
      </Box>
    )
    const todos = p.todos.length > 0 ? (
      <Box gap={1} flexShrink={1}>
        <Text color={done === p.todos.length ? 'success' : 'claude'} tabular>{bar(done, p.todos.length, 8)}</Text>
        <Text bold tabular>{`${done}/${p.todos.length}`}</Text>
        <Text dimColor wrap="truncate-end">{current ? current.activeForm || current.content : done === p.todos.length ? 'todos done' : 'todos'}</Text>
      </Box>
    ) : null

    const controls = (
      <Box gap={1} alignItems="center" flexShrink={0}>
        <Button key="details" label="Details" onPress={() => $.ui.open({ id: PANE, title: 'Pulse' })} />
        <Button key="toggle" label={isCollapsed ? '▲' : '▼'} plain onPress={() => update($, collapsed, v => !v)} />
        <Button key="hide" label="X" role="dismiss" plain dimColor onPress={() => update($, hidden, () => true)} />
      </Box>
    )

    const summary = (
      <Box gap={2} alignItems="center">
        <Box gap={2} flexGrow={1} flexShrink={1} flexWrap="wrap">
          {tools}
          {agents}
          {todos}
        </Box>
        {controls}
      </Box>
    )

    const below = await next(e)
    const rule = (
      <Box width="100%" justifyContent="center">
        <Text dimColor>· · · · ·</Text>
      </Box>
    )
    const stacked = (mine: RenderElement) => isBlank(below)
      ? mine
      : <Box flexDirection="column" gap={1}>{below}{rule}{mine}</Box>
    if (isCollapsed) return stacked(summary)

    // Open: each row says what it lists, in a dim label column.
    const label = (text: string) => (
      <Box width={10} flexShrink={0}>
        <Text dimColor>{text}</Text>
      </Box>
    )
    const top = [...p.tools].sort((a, b) => b.calls - a.calls).slice(0, MAX_TOOLS_SHOWN)
    const toolRow = (
      <Box gap={1}>
        {label('Top tools')}
        <Box flexWrap="wrap" columnGap={3} flexShrink={1}>
          {top.map(t => (
            <Box key={t.name} gap={1}>
              <Text color={t.busy > 0 ? 'claude' : 'text'}>{t.name}</Text>
              <Text dimColor tabular>{`×${t.calls}`}</Text>
              {t.errors > 0 ? <Text color="error" tabular>{`${t.errors} failed`}</Text> : null}
            </Box>
          ))}
          {p.tools.length > top.length ? <Text dimColor>{`+${p.tools.length - top.length} more`}</Text> : null}
        </Box>
      </Box>
    )
    const shownAgents = [...p.agents].sort(byLive).slice(0, MAX_AGENTS_SHOWN)
    const agentRow = (
      <Box gap={1}>
        {label('Agents')}
        <Box flexWrap="wrap" columnGap={3} flexShrink={1}>
          {shownAgents.length === 0 ? <Text dimColor>None this session</Text> : null}
          {shownAgents.map(a => (
            <Box key={a.id} gap={1}>
              <Text color={agentColor(a)}>{agentGlyph(a)}</Text>
              <Text>{a.type}</Text>
              <Text dimColor tabular>{since(a.startedAt, a.endedAt ?? now)}</Text>
            </Box>
          ))}
          {p.agents.length > shownAgents.length ? <Text dimColor>{`+${p.agents.length - shownAgents.length} more`}</Text> : null}
        </Box>
      </Box>
    )

    return stacked(
      <Box flexDirection="column">
        {summary}
        <Box flexDirection="column" marginTop={1} marginLeft={2}>
          {toolRow}
          {agentRow}
        </Box>
      </Box>
    )
  })

  // The pane: the session at a glance, then tools as a table, the latest
  // calls, agents and todos.
  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    const p = await readPulse($)
    const now = await $.clock.now()
    const width = Math.max(40, e.props.bodyColumns)

    const calls = p.tools.reduce((n, t) => n + t.calls, 0)
    const errors = p.tools.reduce((n, t) => n + t.errors, 0)
    const done = p.todos.filter(t => t.status === 'completed').length
    const running = p.agents.filter(a => a.endedAt === null).length
    const sorted = [...p.tools].sort((a, b) => b.calls - a.calls)
    const maxCalls = Math.max(1, ...sorted.map(t => t.calls))
    const isWorking = p.turnStartedAt !== null

    // Columns: name, share bar, calls, failed, avg, last; the bar takes what is left.
    const nameW = Math.min(20, Math.max(6, ...sorted.map(t => t.name.length), ...p.recent.map(r => r.tool.length)))
    const barW = Math.max(4, Math.min(24, width - (nameW + 6 + 7 + 7 + 9) - 10))
    const cell = (w: number, child: RenderElement, right = false) => (
      <Box width={w} flexShrink={0} justifyContent={right ? 'flex-end' : 'flex-start'}>{child}</Box>
    )
    const section = (title: string, note: string) => (
      <Box gap={2}>
        <Text bold>{title}</Text>
        <Text dimColor>{note}</Text>
      </Box>
    )
    const stat = (value: string | number, unit: string, color?: 'error' | 'warning' | 'claude') => (
      <Box gap={1}>
        <Text bold tabular color={color}>{String(value)}</Text>
        <Text dimColor>{unit}</Text>
      </Box>
    )

    const header = (
      <Box flexDirection="column">
        <Box gap={1}>
          <Text color={isWorking ? 'claude' : 'subtle'}>{isWorking ? '◆' : '◇'}</Text>
          <Text bold>{isWorking ? 'Working' : 'Idle'}</Text>
          {isWorking ? <Text dimColor tabular>{`turn ${since(p.turnStartedAt as number, now)}`}</Text> : null}
        </Box>
        <Box gap={3} flexWrap="wrap" marginLeft={2}>
          {stat(p.turns, p.turns === 1 ? 'turn' : 'turns')}
          {stat(calls, calls === 1 ? 'call' : 'calls')}
          {errors > 0 ? stat(errors, 'failed', 'error') : null}
          {stat(running, 'agents running', running > 0 ? 'warning' : undefined)}
          {p.todos.length > 0 ? stat(`${done}/${p.todos.length}`, 'todos') : null}
        </Box>
      </Box>
    )

    const toolTable = (
      <Box flexDirection="column">
        {section('Tools', calls === 0 ? 'None yet' : 'By calls, this session')}
        {sorted.length > 0 ? (
          <Box gap={1}>
            {cell(nameW, <Text dimColor>Tool</Text>)}
            {cell(barW, <Text dimColor>Share</Text>)}
            {cell(6, <Text dimColor>Calls</Text>, true)}
            {cell(7, <Text dimColor>Failed</Text>, true)}
            {cell(7, <Text dimColor>Avg</Text>, true)}
            {cell(9, <Text dimColor>Last</Text>, true)}
          </Box>
        ) : null}
        {sorted.map(t => {
          const finished = Math.max(0, t.calls - t.busy)
          const filled = Math.max(1, Math.round((t.calls / maxCalls) * barW))
          return (
            <Box key={t.name} gap={1}>
              {cell(nameW, <Text color={t.busy > 0 ? 'claude' : 'text'} wrap="truncate-end">{t.name}</Text>)}
              {cell(barW, (
                <Box>
                  <Text color={t.errors > 0 ? 'warning' : 'claude'}>{'█'.repeat(filled)}</Text>
                  <Text dimColor>{'░'.repeat(barW - filled)}</Text>
                </Box>
              ))}
              {cell(6, <Text tabular>{String(t.calls)}</Text>, true)}
              {cell(7, t.errors > 0 ? <Text color="error" tabular>{String(t.errors)}</Text> : <Text dimColor>–</Text>, true)}
              {cell(7, <Text dimColor tabular>{finished > 0 ? ms(t.ms / finished) : '–'}</Text>, true)}
              {cell(9, t.busy > 0 ? <Text color="claude">running</Text> : <Text dimColor tabular>{t.lastAt !== null ? `${since(t.lastAt, now)} ago` : '–'}</Text>, true)}
            </Box>
          )
        })}
      </Box>
    )

    const latest = [...p.recent].reverse().slice(0, RECENT_SHOWN)
    const recentList = (
      <Box flexDirection="column">
        {section('Recent', latest.length === 0 ? 'No calls yet' : `Last ${latest.length} of ${calls}, newest first`)}
        {latest.map(r => (
          <Box key={r.id} gap={1}>
            <Text color={r.endedAt === null ? 'claude' : r.isError ? 'error' : 'success'}>{r.endedAt === null ? '◆' : r.isError ? '✗' : '✓'}</Text>
            {cell(nameW, <Text wrap="truncate-end">{r.tool}</Text>)}
            <Box flexGrow={1} flexShrink={1}>
              <Text dimColor wrap="truncate-end">{r.detail || '–'}</Text>
            </Box>
            {cell(7, r.endedAt === null ? <Text color="claude">running</Text> : <Text dimColor tabular>{ms(r.endedAt - r.startedAt)}</Text>, true)}
            {cell(9, <Text dimColor tabular>{`${since(r.startedAt, now)} ago`}</Text>, true)}
          </Box>
        ))}
      </Box>
    )

    const agentList = [...p.agents].sort(byLive)
    const typeW = Math.min(20, Math.max(6, ...agentList.map(a => a.type.length)))
    const agentSection = (
      <Box flexDirection="column">
        {section('Agents', agentList.length === 0 ? 'None this session' : `${running} running · ${agentList.length - running} done`)}
        {agentList.map(a => (
          <Box key={a.id} gap={1}>
            <Text color={agentColor(a)}>{agentGlyph(a)}</Text>
            {cell(typeW, <Text bold wrap="truncate-end">{a.type}</Text>)}
            <Box flexGrow={1} flexShrink={1}>
              <Text dimColor wrap="truncate-end">{a.description}</Text>
            </Box>
            {cell(9, a.endedAt === null ? <Text color="warning" tabular>{since(a.startedAt, now)}</Text> : <Text dimColor tabular>{since(a.startedAt, a.endedAt)}</Text>, true)}
          </Box>
        ))}
      </Box>
    )

    const todoSection = (
      <Box flexDirection="column">
        {section('Todos', p.todos.length === 0 ? 'No list yet' : `${done} of ${p.todos.length} done`)}
        {p.todos.length > 0 ? <Text color={done === p.todos.length ? 'success' : 'claude'} tabular>{bar(done, p.todos.length, Math.min(32, width - 4))}</Text> : null}
        {p.todos.map((t, i) => (
          <Box key={`${i}-${t.content}`} gap={1}>
            <Text color={t.status === 'completed' ? 'success' : t.status === 'in_progress' ? 'claude' : 'subtle'}>{t.status === 'completed' ? '✓' : t.status === 'in_progress' ? '▶' : '·'}</Text>
            <Text dimColor={t.status === 'completed'} strikethrough={t.status === 'completed'} wrap="wrap">{t.status === 'in_progress' ? t.activeForm || t.content : t.content}</Text>
          </Box>
        ))}
      </Box>
    )

    return (
      <Box flexDirection="column" gap={1}>
        {header}
        {toolTable}
        {recentList}
        {agentSection}
        {todoSection}
      </Box>
    )
  })
}

