export type ToolStat = { name: string; calls: number; errors: number; busy: number; ms: number; lastAt: number | null }
export type CallRow = { id: string; tool: string; detail: string; startedAt: number; endedAt: number | null; isError: boolean }
export type AgentRun = { id: string; type: string; description: string; startedAt: number; endedAt: number | null; isError: boolean }
export type Todo = { content: string; activeForm: string; status: 'pending' | 'in_progress' | 'completed' }
export type Pulse = {
  tools: ToolStat[]
  lastTool: string | null
  agents: AgentRun[]
  todos: Todo[]
  turnStartedAt: number | null
  recent: CallRow[]
  turns: number
}

declare module 'claude-code' {
  interface PluginState {
    pulse: { pulse: Pulse; collapsed: boolean; hidden: boolean }
  }
}
